  result = client.decisions.create(
      model="gemini-decision-1",
      input=[
          {
              "type": "audio",
              "uri": "https://storage.googleapis.com/generativeai-downloads/audio/rehearsing.wav",
              "mime_type": "audio/wav",
          },
      ],
      questions={
          "mentions_launch": {
              "type": "noul",
              "instructions": "Is the speaker talking about a product campaign launch?",
